rows=[
('prepare','Prepare the front circuit','Secure the bike upright on level ground with reservoir top horizontal. Protect paint and plastic. Remove reservoir cap, diaphragm and float; keep parts clean.',[108,110,141],'Bike stable; only the front circuit is being opened.',False),
('drain','Drain and disconnect','Remove caliper union bolt and both copper washers; put hose end in a catch container and pump out fluid. Discard drained fluid and washers.',[139,145],'Entire front circuit drained before caliper disassembly.',False),
('remove','Remove caliper and pads','Remove pad-pin plug and loosen pin. Remove caliper mounting bolts, then pin, pads and both illustrated pad springs. Separate caliper and bracket; release hose holder if needed.',[139,143,144,146],'Keep spring positions matched to diagram139; wheel stays installed.',False),
('pistons','Extract pistons','Contain the pistons with a rag. Apply compressed air through the hose port to expel them; keep clear of their exit. Never pry pistons out. Remove both dust seals, both piston seals and bleed screw.',[140,145],'All four old seals removed; no piston or bore damage from extraction.',False),
('inspect','Inspect the caliper','Replace rusted, scratched or worn pistons. Replace the caliper for cylinder scratches/wear or body cracks/damage; replace a damaged bracket. Clear blocked fluid passages with compressed air.',[145],'Record findings; proceed only with serviceable or correctly replaced parts.',True),
('clean','Clean and renew seals','Wash internal parts with fresh DOT4, never solvent. Install two new piston seals and two new dust seals in their respective diagram140 grooves; use silicone grease at its S-marked seal positions.',[7,140,145,146],'Correct new seals fully seated; piston seal inward of dust seal as illustrated.',False),
('assemble','Reassemble pistons and bracket','Lubricate pistons with fresh DOT4 and install as diagram140. Apply silicone grease at diagram139 sliding-pin locations and reunite bracket/caliper. Install bleed screw at5 Nm.',[7,139,140,146],'Pistons seated without seal damage; sliding assembly moves correctly.',False),
('hose','Reconnect the hose','Position bracket/caliper temporarily. Fit hose with two new copper washers; its pipe portion must contact the caliper stop. Tighten union bolt to30 Nm.',[139,146],'Record new washers, stop contact and30 Nm union torque.',True),
('pads','Restore pads and mounting','Check lining thickness: replace pads as a set at the1.0 mm wear limit. Restore both pad springs to diagram139, engage pad projections in caliper recesses and fit pin temporarily. Secure caliper mounting bolts28 Nm, pin17 Nm and plug2.5 Nm.',[139,144,146],'Record lining assessment and mounting/pin/plug torques; pads correctly retained.',True),
('holder','Secure hose routing','If released, align hose-holder upper edge with the hose paint mark and tighten holder bolt9 Nm. Confirm original routing without strain.',[146],'Holder secured and hose routed as illustrated.',False),
('fill','Fill for bleeding','Fill reservoir to specified level with fresh DOT4 and fit diaphragm. Attach a secure clear hose to bleeder, with its free end in a catch container. Keep reservoir supplied throughout; prevent water entry and overflow.',[108,109,110,146],'Reservoir horizontal; correct fluid and sufficient supply.',False),
('bleed','Remove trapped air','Slowly pump lever several times, then pull fully and hold. Open bleeder; close it before releasing lever. Repeat until hose fluid contains no bubbles, replenishing reservoir. If stubborn tiny bubbles persist, let fluid settle a few hours and repeat.',[110,111],'Record bubble-free result; never allow reservoir to empty.',True),
('close','Close the circuit','Tighten bleeder5 Nm and refit its cap. Restore specified reservoir level with bike upright and reservoir horizontal. Refit float, diaphragm and cap in diagram141 order; cap screws1.5 Nm. Clean spills immediately.',[108,109,111,140,141],'Record final level, bleeder and cap torque; all openings closed.',True),
('verify','Verify brake function','Apply front brake repeatedly and inspect hose/connections for leaks. Lever must not feel soft or spongy; bleed again if it does. After stationary checks pass, check brake effect on a dry test surface before normal riding.',[109,110,147],'Record no leaks, firm lever and proper braking; unresolved faults prevent completion.',True),
]
p=dict(schema_version=1,id='yamaha-2026-yz450f-us-front-caliper-rebuild-v1',component='brakes',affected_components=['front_brake','brakes','fork'],target=dict(manufacturer='Yamaha',model='YZ450F',model_year=2026,region='US',variant='standard'),scope_confirmed=True,title='Rebuild the stock front brake caliper',status='SOURCE_REVIEWED_BOUNDED_PROCEDURE',completeness='Complete stock front-caliper seal/piston service with removal, fluid replacement, bleeding and refit. Serviceable master cylinder, hose and disc required; damaged components need their own replacement operation.',entry_state=['Assembled exact US2026 stock YZ450F; front wheel installed.','Original front master cylinder, hose and disc serviceable; correct replacement caliper seals and any needed pistons/pads available.'],exit_state=['Front caliper rebuilt and secured; hose connected, pads retained and reservoir closed.','Front circuit bled; leak, lever and brake-effect checks passed.'],source=dict(source_url=URL,document_sha256=HASH,document_revision='D03-2819U-10_02',pdf_pages=[7,108,109,110,111,139,140,141,143,144,145,146,147],printed_pages=['symbols','3-24–3-27','4-17–4-25'],review_status='PENDING_INDEPENDENT_REVIEW',review_note='Visual139,140,141,145,146 and110 plus exact text closure. DiagramS means silicone grease; BF means brake fluid. No compressed-air pressure invented.'),applicability=dict(included='Stock front brake on exact US2026 YZ450F',excluded=['Other model years','Replacement aftermarket brake system','Damaged master cylinder/hose/disc requiring separate replacement'],year_inheritance='NONE'),required_tools=[dict(name='Stable support, suitable hand tools and precision torque tools',size='1.5–30 Nm'),dict(name='Compressed-air supply, protective rag and eye protection',size='For controlled piston extraction and clearing passages'),dict(name='Clear bleed hose, waste container and clean fluid-safe trays',size='Fit bleed screw securely'),dict(name='Pad-thickness measuring tool',size='1.0 mm limit')],required_parts=[dict(name='Fresh DOT4 brake fluid',purpose='Cleaning, lubrication and complete front-circuit refill'),dict(name='Two piston seals and two dust seals',purpose='Mandatory caliper renewals'),dict(name='Two new copper union washers',purpose='Caliper hose connection'),dict(name='Silicone grease',purpose='Only diagram-marked seals and sliding pins'),dict(name='Replacement pistons and paired brake pads if inspection requires',purpose='Match exact stock caliper; do not reuse failed parts')],preflight=['Use linked exploded views to identify seal grooves, pad springs and sliding pins.','Keep brake fluid away from eyes, painted surfaces and plastics; contain piston ejection with a rag.'],critical_stop_conditions=['Damaged bore/body/bracket or unserviceable replacement components.','Fluid leaks, persistent air, spongy lever or failed brake-effect check.'],steps=[],publication_status='LOCAL_REVIEW_ONLY_NOT_IMPORTED',reviewed_at='2026-09-13')
